"""Emit quote sheets, social-card text, and retail-ready editorial blurbs."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from .extraction import Quote
from .style import wrap_quotes


@dataclass
class EmitOptions:
    title: str
    social_limit: int = 280


def write_quote_sheet(quotes: list[Quote], options: EmitOptions, path: Path, hash_prefix: str) -> Path:
    lines = [
        f"# Pull Quotes — {options.title}",
        "",
        "_Generated by review-quote-formatter. Every quote below must be verified",
        "_against its source review by a human before publication. Provenance for",
        "_each quote appears in provenance.json (source review lines shown here)._",
        "",
    ]
    for i, quote in enumerate(quotes, 1):
        lines.append(f"{i}. {wrap_quotes(quote.text)}")
        lines.append(f"   — {quote.attribution()}")
        lines.append(
            f"   _Provenance:_ source review #{quote.source_review_index + 1}"
            f" (lines {quote.source.start_line + 1}–{quote.source.end_line + 1} of the pasted input,"
            f" hash {hash_prefix});"
            + (
                f" trimmed, {quote.dropped_words} words dropped — verify against source."
                if quote.dropped_words
                else " untrimmed."
            )
            + ""
        )
        lines.append("")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")
    return path


def write_social_cards(quotes: list[Quote], options: EmitOptions, path: Path) -> Path:
    cards_dir = path / "social"
    cards_dir.mkdir(parents=True, exist_ok=True)
    written: list[Path] = []
    for i, quote in enumerate(quotes, 1):
        card_text = f"{wrap_quotes(quote.text)}\n— {quote.attribution()}\n"
        written_path = cards_dir / f"card-{i:02d}.txt"
        written_path.write_text(card_text, encoding="utf-8")
        written.append(written_path)
    return cards_dir


def write_retail_blurb(quotes: list[Quote], options: EmitOptions, path: Path) -> Path:
    title = options.title or "this book"
    lines = []
    for quote in quotes[:3]:
        lines.append(f"{wrap_quotes(quote.text)} — {quote.attribution()}")
    body = "\n".join(lines)
    blurb = (
        f"# Retail Blurb — {title}\n\n"
        "Praise for the book:\n\n"
        f"{body}\n\n"
        f"{title} is available in paperback and ebook from all major retailers.\n"
        "\n---\n"
        "Copy produced by review-quote-formatter (Asdale Dynamics, LLC); verify every"
        " quote against its source review before publishing.\n"
    )
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(blurb, encoding="utf-8")
    return path
